{
  "name": "Newport 1830C 光功率计",
  "name_en": "Newport 1830C Optical Power Meter",
  "manufacturer": "Newport",
  "description": "用于测量光信号功率的台式光功率计，可进行波长补偿、量程设置、零点扣除、参考值存储和自动校准，适合激光与光学实验中的功率监测与定量测量。",
  "description_en": "A benchtop optical power meter for measuring optical signal power. It supports wavelength compensation, range selection, zero subtraction, reference storage, and auto calibration, making it suitable for power monitoring and quantitative measurements in laser and optics experiments.",
  "tag_hints": [
    "optical power measurement",
    "laser power monitoring",
    "wavelength compensation",
    "auto ranging",
    "reference power measurement",
    "zero subtraction",
    "benchtop photometry"
  ],
  "actions": [
    {
      "action_name": "auto-autocalibration_async",
      "description": "异步执行光功率计自动校准，以断开输入信号并完成内部校准。",
      "description_en": "Asynchronously perform the power meter auto-calibration procedure, disconnecting the input signal for internal calibration."
    },
    {
      "action_name": "auto-store_reference_async",
      "description": "异步将当前输入光功率保存为参考功率，用于后续参考测量。",
      "description_en": "Asynchronously store the current input optical power as the reference level for subsequent relative measurements."
    },
    {
      "action_name": "auto-attenuator",
      "description": "获取或设置衰减器状态。",
      "description_en": "Get or set the attenuator state."
    },
    {
      "action_name": "auto-beeper",
      "description": "获取或设置蜂鸣提示音开关。",
      "description_en": "Get or set the audible beeper on/off state."
    },
    {
      "action_name": "auto-data",
      "description": "读取当前光功率测量值。",
      "description_en": "Read the current optical power measurement value."
    },
    {
      "action_name": "auto-echo",
      "description": "获取或设置串口通信回显模式。",
      "description_en": "Get or set the RS-232 communication echo mode."
    },
    {
      "action_name": "auto-filter",
      "description": "获取或设置测量平均滤波速度。",
      "description_en": "Get or set the measurement averaging filter speed."
    },
    {
      "action_name": "auto-go",
      "description": "获取或设置是否允许仪器进行新的测量。",
      "description_en": "Get or set whether the instrument is enabled to take new measurements."
    },
    {
      "action_name": "auto-keypad",
      "description": "获取或设置按键面板与显示背光亮度。",
      "description_en": "Get or set the keypad and display backlight intensity."
    },
    {
      "action_name": "auto-lockout",
      "description": "获取或设置前面板锁定状态，以禁用按键操作。",
      "description_en": "Get or set the front-panel lockout state to disable keypad operation."
    },
    {
      "action_name": "auto-autocalibration",
      "description": "执行光功率计自动校准，以完成内部校准补偿。",
      "description_en": "Perform the power meter auto-calibration procedure for internal calibration compensation."
    },
    {
      "action_name": "auto-range",
      "description": "获取或设置信号测量量程，包括自动量程模式。",
      "description_en": "Get or set the signal measurement range, including auto-ranging mode."
    },
    {
      "action_name": "auto-store_reference",
      "description": "将当前输入光功率保存为参考功率。",
      "description_en": "Store the current input optical power as the reference level."
    },
    {
      "action_name": "auto-units",
      "description": "获取或设置功率测量单位。",
      "description_en": "Get or set the power measurement units."
    },
    {
      "action_name": "auto-wavelength",
      "description": "获取或设置输入光信号的波长补偿值。",
      "description_en": "Get or set the wavelength compensation value for the input optical signal."
    },
    {
      "action_name": "auto-zero",
      "description": "获取或设置零点扣除功能，用于去除背景功率。",
      "description_en": "Get or set the zero function used to subtract background power."
    }
  ]
}

